const ctx = $('Input').first().json;
const m = String(ctx.drive_tax_folder ?? '').match(/[-\w]{25,}/);
return [{ json: { ...ctx, tax_folder_id: m ? m[0] : '' } }];

const files = ($json.files ?? []).slice(0, 3);
if (!files.length) { return [{ json: { no_docs: true } }]; }
return files.map(f => ({ json: f }));

const ctx = $('Input').first().json;
const items = $input.all();
const docs = [];
for (const it of items) {
  const b64 = it.binary?.data?.data;
  if (b64) docs.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } });
}
if (!docs.length) { return [{ json: { ...ctx, tax_position: { notes: ['No tax documents found'], tax_year: null, agi: null, taxable_income: null, marginal_rate: null, effective_rate: null, carryforwards: [], elections: [], estimates_paid: null, safe_harbor_target: null } } }]; }
const payload = {
  model: 'claude-opus-4-8', max_tokens: 8000,
  system: "You are extracting structured tax data from a client's tax returns and prior tax plans for internal use by a CPA. Extract only values that are explicitly present in the documents. Never estimate or fill gaps \u2014 use null for anything not found. This feeds a tax projection, so accuracy matters more than completeness. Output only the JSON schema.",
  messages: [{ role: 'user', content: [...docs, { type: 'text', text: 'Extract the tax position for client ' + ctx.client_name + '.' }] }],
  output_config: { effort: 'high', format: { type: 'json_schema', schema: {"type": "object", "additionalProperties": false, "required": ["tax_year", "agi", "taxable_income", "marginal_rate", "effective_rate", "carryforwards", "elections", "estimates_paid", "safe_harbor_target", "notes"], "properties": {"tax_year": {"type": ["string", "null"]}, "agi": {"type": ["number", "null"]}, "taxable_income": {"type": ["number", "null"]}, "marginal_rate": {"type": ["number", "null"]}, "effective_rate": {"type": ["number", "null"]}, "carryforwards": {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["type", "amount"], "properties": {"type": {"type": "string"}, "amount": {"type": ["number", "null"]}}}}, "elections": {"type": "array", "items": {"type": "string"}}, "estimates_paid": {"type": ["number", "null"]}, "safe_harbor_target": {"type": ["number", "null"]}, "notes": {"type": "array", "items": {"type": "string"}}}} } }
};
return [{ json: { payload } }];

const ctx = $('Input').first().json;
if ($json.tax_position) { return [{ json: $json }]; }
const text = $json.content?.[0]?.text ?? '{}';
let out; try { out = JSON.parse(text); } catch (e) { out = { parse_error: true, raw: text }; }
return [{ json: { ...ctx, tax_position: out } }];
